/// Generous bound after which a dead `doctor --fix` owner's leftovers stop
/// blocking new repairs (cass#368). Deliberately much larger than
/// [`DOCTOR_LOCK_HEARTBEAT_STALE_AFTER_MS`]: suspecting staleness only makes
/// diagnostics honest, while reclaiming re-arms a mutating repair.
pub(crate) const DOCTOR_STALE_SELF_HEAL_AFTER_MS: u64 = 24 * 60 * 60 * 1000;


pub(crate) struct DoctorStaleSelfHealSummary {
    pub(crate) receipt_path: PathBuf,
    pub(crate) reclaimed_marker_files: usize,
    pub(crate) lock_metadata_cleared: bool,
}


pub(crate) fn doctor_file_mtime_age_ms(path: &Path, now_ms: i64) -> Option<u64> {
    let modified = std::fs::metadata(path).ok()?.modified().ok()?;
    doctor_elapsed_since_ms(now_ms, system_time_to_unix_ms(modified))
}


/// Self-heal for the cass#368 dead end: a `doctor --fix` that crashed mid
/// `repair_apply` leaves the mutation-lock file with dead-owner metadata and
/// a repair failure marker, and every later `--fix` refuses with
/// `manual_delete_allowed: false` — forever.
///
/// Reclaim is evidence-gated, in line with the #176 index-run doctrine that
/// flock acquisition (not pid probing, which breaks under pid reuse) is the
/// proof that the recorded owner is gone:
///
/// * the mutation flock must be acquirable (owner provably gone), AND
/// * the lock file must carry metadata whose heartbeat is older than
///   [`DOCTOR_STALE_SELF_HEAL_AFTER_MS`] — i.e. a *crashed* owner, not a
///   repair that failed cleanly and released the lock.
///
/// Only then is the failure marker (itself older than the bound) moved —
/// never deleted — into `doctor/reclaimed/<ts>-stale-repair-state/` with a
/// receipt, and the stale lock metadata truncated in place while the flock
/// is held (the metadata is preserved verbatim in the receipt). A marker
/// without crashed-owner lock evidence is a deliberate fail-closed record of
/// a completed-but-failed repair and continues to require
/// `--allow-repeated-repair`.
pub(crate) fn doctor_self_heal_stale_repair_state(
    data_dir: &Path,
    repair_class: &str,
) -> Option<DoctorStaleSelfHealSummary> {
    let now_ms = doctor_now_ms();
    let lock_path = doctor_mutation_lock_path(data_dir);
    if !lock_path.exists() {
        return None;
    }
    let file = OpenOptions::new()
        .read(true)
        .write(true)
        .open(&lock_path)
        .ok()?;
    if fs2::FileExt::try_lock_exclusive(&file).is_err() {
        // A live owner (or an uninspectable lock): never heal underneath it.
        return None;
    }

    let outcome = (|| {
        let metadata = doctor_read_lock_metadata(&file);
        if metadata.is_empty() {
            return None;
        }
        let heartbeat_age_ms = doctor_elapsed_since_ms(
            now_ms,
            doctor_lock_metadata_i64(&metadata, "updated_at_ms")
                .or_else(|| doctor_lock_metadata_i64(&metadata, "started_at_ms")),
        )
        .or_else(|| doctor_file_mtime_age_ms(&lock_path, now_ms));
        if !heartbeat_age_ms.is_some_and(|age| age > DOCTOR_STALE_SELF_HEAL_AFTER_MS) {
            return None;
        }

        let marker = collect_doctor_repair_failure_marker(data_dir, repair_class);
        let marker_age_ms = marker
            .found
            .then(|| {
                doctor_elapsed_since_ms(now_ms, marker.failed_at_ms).or_else(|| {
                    marker
                        .path
                        .as_deref()
                        .and_then(|path| doctor_file_mtime_age_ms(Path::new(path), now_ms))
                })
            })
            .flatten();
        let reclaim_marker = marker_age_ms.is_some_and(|age| age > DOCTOR_STALE_SELF_HEAL_AFTER_MS);

        let stamp = chrono::DateTime::<chrono::Utc>::from_timestamp_millis(now_ms)
            .map(|dt| dt.format("%Y%m%dT%H%M%SZ").to_string())
            .unwrap_or_else(|| now_ms.to_string());
        let reclaim_dir = data_dir
            .join("doctor")
            .join("reclaimed")
            .join(format!("{stamp}-stale-repair-state"));
        std::fs::create_dir_all(&reclaim_dir).ok()?;

        let mut moved_markers = Vec::new();
        if reclaim_marker {
            let marker_dir = doctor_repair_failure_marker_dir(data_dir, repair_class);
            if let Ok(entries) = std::fs::read_dir(&marker_dir) {
                for entry in entries.flatten() {
                    let from = entry.path();
                    if from.extension().and_then(|ext| ext.to_str()) != Some("json") {
                        continue;
                    }
                    let Some(name) = from.file_name() else {
                        continue;
                    };
                    let to = reclaim_dir.join(name);
                    if std::fs::rename(&from, &to).is_ok() {
                        moved_markers.push(serde_json::json!({
                            "from": from.display().to_string(),
                            "to": to.display().to_string(),
                        }));
                    }
                }
            }
        }

        let receipt = serde_json::json!({
            "schema_version": 1,
            "kind": "cass_doctor_stale_repair_state_reclaim_v1",
            "reclaimed_at_ms": now_ms,
            "repair_class": repair_class,
            "self_heal_bound_ms": DOCTOR_STALE_SELF_HEAL_AFTER_MS,
            "lock": {
                "path": lock_path.display().to_string(),
                "heartbeat_age_ms": heartbeat_age_ms,
                "metadata": metadata,
                "metadata_cleared": true,
            },
            "marker": {
                "found": marker.found,
                "age_ms": marker_age_ms,
                "parse_status": marker.parse_status,
                "reclaimed": reclaim_marker,
                "moved": moved_markers,
            },
            "rationale": "previous doctor --fix owner is provably gone (mutation flock \
                          acquired) and its heartbeat exceeded the self-heal bound; the \
                          crashed repair's leftovers were reclaimed with this receipt \
                          instead of blocking repairs indefinitely (cass#368)",
        });
        let receipt_path = reclaim_dir.join("receipt.json");
        let encoded = serde_json::to_vec_pretty(&receipt).ok()?;
        std::fs::write(&receipt_path, encoded).ok()?;

        // Reap the stale metadata in place while holding the flock (the #176
        // index-run pattern); the metadata lives on inside the receipt.
        if file.set_len(0).is_ok() {
            let _ = file.sync_all();
        }

        tracing::info!(
            lock_path = %lock_path.display(),
            receipt = %receipt_path.display(),
            reclaimed_marker_files = moved_markers.len(),
            heartbeat_age_ms,
            "doctor self-heal reclaimed stale repair state from a dead --fix owner (cass#368)"
        );

        Some(DoctorStaleSelfHealSummary {
            receipt_path,
            reclaimed_marker_files: moved_markers.len(),
            lock_metadata_cleared: true,
        })
    })();

    let _ = fs2::FileExt::unlock(&file);
    outcome
}


pub(crate) fn collect_doctor_repair_failure_marker(
    data_dir: &Path,
    repair_class: &str,
) -> DoctorRepairFailureMarkerReport {
    let marker_dir = doctor_repair_failure_marker_dir(data_dir, repair_class);
    let entries = match std::fs::read_dir(&marker_dir) {
        Ok(entries) => entries,
        Err(err) if err.kind() == io::ErrorKind::NotFound => {
            return doctor_failure_marker_absent_report(repair_class);
        }
        Err(err) => {
            return doctor_failure_marker_corrupt_report(
                data_dir,
                repair_class,
                &marker_dir,
                format!("failed to read failure marker directory: {err}"),
            );
        }
    };

    let mut marker_paths = entries
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|path| path.extension().and_then(|ext| ext.to_str()) == Some("json"))
        .collect::<Vec<_>>();
    marker_paths.sort();

    let Some(path) = marker_paths.pop() else {
        return doctor_failure_marker_absent_report(repair_class);
    };

    let content = match std::fs::read_to_string(&path) {
        Ok(content) => content,
        Err(err) => {
            return doctor_failure_marker_corrupt_report(
                data_dir,
                repair_class,
                &path,
                format!("failed to read failure marker: {err}"),
            );
        }
    };
    let marker = match serde_json::from_str::<DoctorRepairFailureMarker>(&content) {
        Ok(marker) => marker,
        Err(err) => {
            return doctor_failure_marker_corrupt_report(
                data_dir,
                repair_class,
                &path,
                format!("failed to parse failure marker JSON: {err}"),
            );
        }
    };
    if marker.marker_kind != DOCTOR_REPAIR_FAILURE_MARKER_KIND {
        return doctor_failure_marker_corrupt_report(
            data_dir,
            repair_class,
            &path,
            format!("unexpected marker_kind {}", marker.marker_kind),
        );
    }
    if marker.schema_version != DOCTOR_REPAIR_FAILURE_MARKER_SCHEMA_VERSION {
        return doctor_failure_marker_corrupt_report(
            data_dir,
            repair_class,
            &path,
            format!("unsupported schema_version {}", marker.schema_version),
        );
    }
    if marker.repair_class != repair_class {
        return doctor_failure_marker_corrupt_report(
            data_dir,
            repair_class,
            &path,
            format!(
                "marker repair_class {} did not match {repair_class}",
                marker.repair_class
            ),
        );
    }

    doctor_failure_marker_report_from_marker(data_dir, &path, marker)
}


pub(crate) fn doctor_repair_failure_marker_refusal_reason(
    report: &DoctorRepairFailureMarkerReport,
) -> Option<String> {
    if !report.found {
        return None;
    }
    let path = report
        .redacted_path
        .as_deref()
        .or(report.path.as_deref())
        .unwrap_or("[unknown-marker]");
    Some(format!(
        "previous {} repair failure marker at {path} blocks repeated mutation until --allow-repeated-repair is supplied",
        report.repair_class
    ))
}


pub(crate) fn doctor_failure_marker_file_stem(operation_id: &str, failed_at_ms: i64) -> String {
    let safe_operation_id = operation_id
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || ch == '-' || ch == '_' {
                ch
            } else {
                '-'
            }
        })
        .collect::<String>();
    format!("{failed_at_ms}-{safe_operation_id}")
}


pub(crate) fn write_doctor_repair_failure_marker(
    data_dir: &Path,
    marker: &DoctorRepairFailureMarker,
) -> Result<PathBuf, String> {
    let marker_dir = doctor_repair_failure_marker_dir(data_dir, &marker.repair_class);
    std::fs::create_dir_all(&marker_dir).map_err(|err| {
        format!(
            "failed to create doctor repair failure marker directory {}: {err}",
            marker_dir.display()
        )
    })?;
    if existing_path_has_symlink_below_root(&marker_dir, data_dir) {
        return Err(format!(
            "refusing to write doctor repair failure marker through symlinked path {}",
            marker_dir.display()
        ));
    }

    let stem = doctor_failure_marker_file_stem(&marker.operation_id, marker.failed_at_ms);
    let payload = serde_json::to_vec_pretty(marker)
        .map_err(|err| format!("failed to serialize doctor repair failure marker: {err}"))?;
    for attempt in 0..100 {
        let file_name = if attempt == 0 {
            format!("{stem}.json")
        } else {
            format!("{stem}~{attempt}.json")
        };
        let path = marker_dir.join(file_name);
        match OpenOptions::new().write(true).create_new(true).open(&path) {
            Ok(mut file) => {
                file.write_all(&payload).map_err(|err| {
                    format!(
                        "failed to write doctor repair failure marker {}: {err}",
                        path.display()
                    )
                })?;
                file.sync_all().map_err(|err| {
                    format!(
                        "failed to sync doctor repair failure marker {}: {err}",
                        path.display()
                    )
                })?;
                sync_directory(&marker_dir)?;
                return Ok(path);
            }
            Err(err) if err.kind() == io::ErrorKind::AlreadyExists => continue,
            Err(err) => {
                return Err(format!(
                    "failed to create doctor repair failure marker {}: {err}",
                    path.display()
                ));
            }
        }
    }
    Err(format!(
        "failed to create unique doctor repair failure marker under {}",
        marker_dir.display()
    ))
}


pub(crate) fn doctor_failure_marker_artifact_for_class(
    data_dir: &Path,
    db_path: &Path,
    index_path: &Path,
    asset_class: DoctorAssetClass,
) -> DoctorRepairFailureMarkerArtifact {
    let owned_path;
    let path = match asset_class {
        DoctorAssetClass::CanonicalArchiveDb | DoctorAssetClass::ArchiveDbSidecar => db_path,
        DoctorAssetClass::DerivedLexicalIndex | DoctorAssetClass::ReclaimableDerivedCache => {
            index_path
        }
        DoctorAssetClass::OperationReceipt
        | DoctorAssetClass::EventLog
        | DoctorAssetClass::ForensicBundle => {
            owned_path = data_dir.join("doctor");
            &owned_path
        }
        DoctorAssetClass::RawMirrorBlob => {
            owned_path = data_dir.join("raw-mirror").join("v1");
            &owned_path
        }
        _ => data_dir,
    };
    let path_text = path.display().to_string();
    DoctorRepairFailureMarkerArtifact {
        artifact_kind: "doctor_affected_asset".to_string(),
        asset_class: doctor_serde_label(asset_class),
        redacted_path: doctor_redacted_path(&path_text, data_dir),
        path: path_text,
    }
}


pub(crate) struct DoctorRepairFailureMarkerBuildContext<'a> {
    pub(crate) data_dir: &'a Path,
    pub(crate) db_path: &'a Path,
    pub(crate) index_path: &'a Path,
    pub(crate) repair_class: &'a str,
    pub(crate) operation_id: &'a str,
    pub(crate) plan_fingerprint: &'a str,
    pub(crate) command_line_mode: &'a str,
    pub(crate) check_reports: &'a [DoctorCheckReport],
    pub(crate) auto_fix_actions: &'a [String],
    pub(crate) fs_mutation_receipts: &'a [DoctorFsMutationReceipt],
    pub(crate) operation_outcome: &'a DoctorOperationOutcomeReport,
    pub(crate) cleanup_apply_result: Option<&'a DiagCleanupApplyResult>,
}


pub(crate) fn build_doctor_repair_failure_marker(
    context: DoctorRepairFailureMarkerBuildContext<'_>,
) -> DoctorRepairFailureMarker {
    let mut affected_classes = context
        .check_reports
        .iter()
        .filter(|check| check.status != "pass")
        .map(|check| check.affected_asset_class)
        .collect::<Vec<_>>();
    affected_classes.sort_by_key(|class| doctor_serde_label(*class));
    affected_classes.dedup();
    let affected_artifacts = affected_classes
        .into_iter()
        .map(|asset_class| {
            doctor_failure_marker_artifact_for_class(
                context.data_dir,
                context.db_path,
                context.index_path,
                asset_class,
            )
        })
        .collect::<Vec<_>>();

    let failed_checks = context
        .check_reports
        .iter()
        .filter(|check| check.status == "fail")
        .map(|check| format!("{}:{}", check.name, check.anomaly_class_label()))
        .collect::<Vec<_>>();
    let verification_checks = context
        .check_reports
        .iter()
        .map(|check| format!("{}:{}", check.name, check.status))
        .collect::<Vec<_>>();
    let applied_actions = context
        .auto_fix_actions
        .iter()
        .cloned()
        .chain(
            context
                .fs_mutation_receipts
                .iter()
                .filter(|receipt| receipt.status == DoctorActionStatus::Applied)
                .map(|receipt| {
                    format!(
                        "{}:{}",
                        doctor_serde_label(receipt.mutation_kind),
                        receipt.redacted_target_path
                    )
                }),
        )
        .collect::<Vec<_>>();
    let selected_authorities = context
        .cleanup_apply_result
        .and_then(|result| result.plan.as_ref())
        .map(|plan| plan.selected_authorities.clone())
        .unwrap_or_else(|| {
            vec![
                "doctor_anomaly_taxonomy_v1".to_string(),
                "doctor_repair_mode_policy_v1".to_string(),
                "doctor_check_report_v1".to_string(),
            ]
        });
    let rejected_authorities = context
        .cleanup_apply_result
        .and_then(|result| result.plan.as_ref())
        .map(|plan| plan.rejected_authorities.clone())
        .unwrap_or_default();
    let user_data_modified = context
        .auto_fix_actions
        .iter()
        .any(|action| action.contains("Backed up corrupted database bundle"));

    DoctorRepairFailureMarker {
        marker_kind: DOCTOR_REPAIR_FAILURE_MARKER_KIND.to_string(),
        schema_version: DOCTOR_REPAIR_FAILURE_MARKER_SCHEMA_VERSION,
        repair_class: context.repair_class.to_string(),
        operation_id: context.operation_id.to_string(),
        command_line_mode: context.command_line_mode.to_string(),
        plan_fingerprint: context.plan_fingerprint.to_string(),
        affected_artifacts,
        selected_authorities,
        rejected_authorities,
        preflight_checks: verification_checks.clone(),
        applied_actions,
        verification_checks,
        failed_checks,
        forensic_bundle_path: context
            .cleanup_apply_result
            .and_then(|result| result.plan.as_ref())
            .and_then(|plan| plan.forensic_bundle.path.clone())
            .or_else(|| {
                context
                    .fs_mutation_receipts
                    .iter()
                    .find_map(|receipt| receipt.forensic_bundle.path.clone())
            }),
        candidate_path: None,
        started_at_ms: context
            .cleanup_apply_result
            .and_then(|result| result.operation_started_at_ms),
        failed_at_ms: doctor_now_ms(),
        cass_version: env!("CARGO_PKG_VERSION").to_string(),
        platform: format!("{}/{}", std::env::consts::OS, std::env::consts::ARCH),
        user_data_modified,
        operation_outcome_kind: doctor_serde_label(context.operation_outcome.kind),
    }
}


pub(crate) fn doctor_artifact_descriptor_blake3(
    artifact_kind: &str,
    asset_class: DoctorAssetClass,
    path: &str,
    size_bytes: Option<u64>,
) -> String {
    doctor_canonical_blake3(
        "doctor-artifact-descriptor-v1",
        serde_json::json!({
            "artifact_kind": artifact_kind,
            "asset_class": asset_class,
            "path": path,
            "size_bytes": size_bytes,
        }),
    )
}


pub(crate) fn doctor_artifact_from_cleanup_action(
    action: &DiagCleanupApplyAction,
    data_dir: &Path,
) -> DoctorArtifact {
    let exists = Path::new(&action.path).exists();
    let size_bytes = Some(action.planned_reclaimable_bytes);
    let checksum_status = if action.applied {
        DoctorArtifactChecksumStatus::NotRecorded
    } else {
        doctor_artifact_checksum_status(exists, None, None)
    };
    DoctorArtifact {
        artifact_id: doctor_canonical_blake3(
            "doctor-artifact-v1",
            serde_json::json!({
                "artifact_kind": action.artifact_kind,
                "asset_class": action.asset_safety.asset_class,
                "path": action.path,
                "generation_id": action.generation_id,
                "shard_id": action.shard_id,
                "planned_reclaimable_bytes": action.planned_reclaimable_bytes,
            }),
        ),
        artifact_kind: action.artifact_kind.clone(),
        asset_class: action.asset_safety.asset_class,
        path: action.path.clone(),
        redacted_path: doctor_redacted_path(&action.path, data_dir),
        exists,
        size_bytes,
        descriptor_blake3: doctor_artifact_descriptor_blake3(
            &action.artifact_kind,
            action.asset_safety.asset_class,
            &action.path,
            size_bytes,
        ),
        expected_content_blake3: None,
        actual_content_blake3: None,
        checksum_status,
    }
}


pub(crate) fn doctor_manifest_drift_status(artifacts: &[DoctorArtifact]) -> DoctorDriftDetectionStatus {
    if artifacts
        .iter()
        .any(|artifact| artifact.checksum_status == DoctorArtifactChecksumStatus::Missing)
    {
        DoctorDriftDetectionStatus::MissingArtifact
    } else if artifacts
        .iter()
        .any(|artifact| artifact.checksum_status == DoctorArtifactChecksumStatus::Mismatched)
    {
        DoctorDriftDetectionStatus::ChecksumMismatch
    } else if !artifacts.is_empty()
        && artifacts
            .iter()
            .all(|artifact| artifact.checksum_status == DoctorArtifactChecksumStatus::Matched)
    {
        DoctorDriftDetectionStatus::Verified
    } else {
        DoctorDriftDetectionStatus::NotChecked
    }
}


pub(crate) fn doctor_artifact_manifest(artifacts: Vec<DoctorArtifact>) -> DoctorArtifactManifest {
    let drift_detection_status = doctor_manifest_drift_status(&artifacts);
    let manifest_blake3 = doctor_canonical_blake3(
        "doctor-artifact-manifest-v1",
        serde_json::json!({
            "schema_version": 1,
            "artifacts": artifacts,
            "drift_detection_status": drift_detection_status,
        }),
    );
    DoctorArtifactManifest {
        schema_version: 1,
        artifact_count: artifacts.len(),
        manifest_blake3,
        drift_detection_status,
        artifacts,
    }
}


pub(crate) fn doctor_cleanup_coverage_snapshot(
    generation_count: usize,
    reclaim_candidate_count: usize,
    reclaimable_bytes: u64,
    retained_bytes: u64,
    actions: &[DiagCleanupApplyAction],
) -> DoctorCoverageSnapshot {
    let mut covered_asset_classes: Vec<_> = actions
        .iter()
        .map(|action| action.asset_safety.asset_class)
        .collect();
    covered_asset_classes.sort_by_key(|class| format!("{class:?}"));
    covered_asset_classes.dedup();
    DoctorCoverageSnapshot {
        generation_count,
        reclaim_candidate_count,
        reclaimable_bytes,
        retained_bytes,
        artifact_count: actions.len(),
        covered_asset_classes,
    }
}


pub(crate) fn doctor_safety_gate_for_cleanup_action(
    action: &DiagCleanupApplyAction,
    data_dir: &Path,
    db_path: &Path,
    index_path: &Path,
    approval_fingerprint: &str,
) -> DoctorSafetyGate {
    let asset_class = action.asset_safety.asset_class;
    let allowed_by_mode =
        doctor_repair_mode_allows_asset_mutation(DoctorRepairMode::CleanupApply, asset_class);
    let allowed_by_taxonomy = doctor_asset_safe_to_gc(asset_class, true);
    let path_safe = action.applied
        || cleanup_target_path_is_safe(Path::new(&action.path), data_dir, db_path, index_path);
    let mut blocked_reasons = Vec::new();
    if !allowed_by_mode {
        blocked_reasons.push("mode_disallows_asset_class".to_string());
    }
    if !allowed_by_taxonomy {
        blocked_reasons.push("taxonomy_disallows_automatic_reclaim".to_string());
    }
    if !path_safe {
        blocked_reasons.push("unsafe_or_missing_path".to_string());
    }
    if let Some(skip_reason) = action.skip_reason.as_ref() {
        blocked_reasons.push(skip_reason.clone());
    }
    DoctorSafetyGate {
        mode: DoctorRepairMode::CleanupApply,
        asset_class,
        allowed_by_mode,
        allowed_by_taxonomy,
        path_safe,
        approval_requirement: DoctorApprovalRequirement::ApprovalFingerprint,
        approval_fingerprint: approval_fingerprint.to_string(),
        passed: blocked_reasons.is_empty(),
        blocked_reasons,
    }
}


pub(crate) fn doctor_cleanup_action_id(action: &DiagCleanupApplyAction) -> String {
    doctor_canonical_blake3(
        "doctor-action-v1",
        serde_json::json!({
            "action_kind": action.artifact_kind,
            "mode": DoctorRepairMode::CleanupApply,
            "asset_class": action.asset_safety.asset_class,
            "target_path": action.path,
            "generation_id": action.generation_id,
            "shard_id": action.shard_id,
            "planned_bytes": action.planned_reclaimable_bytes,
            "reason": action.reason,
        }),
    )
}


pub(crate) fn doctor_action_from_cleanup_action(
    action: &DiagCleanupApplyAction,
    status: DoctorActionStatus,
    data_dir: &Path,
    db_path: &Path,
    index_path: &Path,
    approval_fingerprint: &str,
) -> DoctorAction {
    let artifact = doctor_artifact_from_cleanup_action(action, data_dir);
    let safety_gate = doctor_safety_gate_for_cleanup_action(
        action,
        data_dir,
        db_path,
        index_path,
        approval_fingerprint,
    );
    let mut remaining_risk = Vec::new();
    if matches!(
        status,
        DoctorActionStatus::Skipped | DoctorActionStatus::Blocked | DoctorActionStatus::Failed
    ) {
        remaining_risk.push(
            action
                .skip_reason
                .clone()
                .unwrap_or_else(|| "planned cleanup did not apply".to_string()),
        );
    }
    let authority_decision = if safety_gate.passed {
        "allowed_by_taxonomy_and_path_gate"
    } else {
        "blocked_by_taxonomy_or_path_gate"
    }
    .to_string();
    let selected_authorities = vec![
        "doctor_asset_taxonomy_v1".to_string(),
        "lexical_cleanup_dry_run_v1".to_string(),
    ];
    let rejected_authorities = if safety_gate.passed {
        Vec::new()
    } else {
        safety_gate.blocked_reasons.clone()
    };
    let verification_outcome = match status {
        DoctorActionStatus::Planned => "pending_apply",
        DoctorActionStatus::Applied => "applied",
        DoctorActionStatus::Skipped => "skipped",
        DoctorActionStatus::Blocked => "blocked",
        DoctorActionStatus::Failed => "failed",
        DoctorActionStatus::Refused => "refused",
    }
    .to_string();
    let bytes_pruned = if status == DoctorActionStatus::Applied {
        action.reclaimed_bytes
    } else {
        0
    };
    let action_id = doctor_cleanup_action_id(action);
    DoctorAction {
        action_id,
        action_kind: action.artifact_kind.clone(),
        status,
        mode: DoctorRepairMode::CleanupApply,
        asset_class: action.asset_safety.asset_class,
        target_path: action.path.clone(),
        redacted_target_path: doctor_redacted_path(&action.path, data_dir),
        reason: action.reason.clone(),
        authority_decision,
        selected_authorities,
        rejected_authorities,
        safety_gate,
        planned_bytes: action.planned_reclaimable_bytes,
        bytes_copied: 0,
        bytes_moved: 0,
        bytes_pruned,
        backup_paths: Vec::new(),
        verification_outcome,
        remaining_risk,
        artifacts: vec![artifact],
    }
}
